//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_etn.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/etn_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
scwin.vScrenID = "ULDSTF08076.xml";
scwin.fr_SecuGrpId = SECUGRP_ID_EN; // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조. 
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.TR_JOB;
scwin.procJob;
scwin.vViewCorrYnTyp = '1'; //신규상장신청 
scwin.vIdxIndCd = "";
scwin.vCurDate;
scwin.checkResult;
scwin.checkDateTPlus2;
scwin.checkDateTMinus2;
scwin.mktHoldyYn;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/**
 * 공통코드 조회
 */
scwin.fn_searchCode = function() {
    /*		
    03685	ISU_AGNT_TP_CD							발행대행기관		
    03698	ETN_BZ_ADM_COM_TP_CD			사무관리회사		
    02323	TAX_TP_CD									과세유형			
    03686	DISTR_TP_CD								분배금형태코드
    01650	DRV_CLSS_LST_SETL_METHD_CD	결제방법		
    */
    var arrCid = [ //발행증권에 관한 사항
        {
            cid: "ISU_AGNT_TP_CD",
            cnm: "cmb_ISU_AGNT_TP_CD"
        }, {
            cid: "ETN_BZ_ADM_COM_TP_CD",
            cnm: "cmb_ETN_BZ_ADM_COM_TP_CD"
        }, {
            cid: "TAX_TP_CD",
            cnm: "cmb_TAX_TP_CD"
        }, {
            cid: "DISTR_TP_CD",
            cnm: "cmb_DISTR_TP_CD"
        }, {
            cid: "DRV_CLSS_LST_SETL_METHD_CD",
            cnm: "cmb_LST_SETL_METHD_CD"
        }, {
            cid: "LOSS_LMT_ETN_EARNG_STRUCT_CD",
            cnm: "cmb_EARNG_STRUCT_TP_CD"
        }, {
            cid: "ETN_EARY_REDMPT_CYCLE_CD",
            cnm: "cmb_EARY_REDMPT_CYCLE_CD"
        }, {
            cid: "VALU_PRC_CALC_INST_CD",
            cnm: "cmb_VALU_PRC1_CALC_INST_CD"
        }, {
            cid: "VALU_MDL_CD",
            cnm: "cmb_VALU_PRC1_VALU_MDL_CD"
        }, {
            cid: "VOLT_KIND_CD",
            cnm: "cmb_VALU_PRC1_VOLT_KIND_CD"
        }, {
            cid: "VOLT_CURSFC_EXST_CD",
            cnm: "cmb_VALU_PRC1_VOLT_CURSFC_CD"
        }, {
            cid: "DRV_CLSS_DIV_TP_CD",
            cnm: "cmb_VALU_PRC1_DIV_CD"
        }, {
            cid: "VALU_PRC_CALC_INST_CD",
            cnm: "cmb_VALU_PRC2_CALC_INST_CD"
        }, {
            cid: "VALU_MDL_CD",
            cnm: "cmb_VALU_PRC2_VALU_MDL_CD"
        }, {
            cid: "VOLT_KIND_CD",
            cnm: "cmb_VALU_PRC2_VOLT_KIND_CD"
        }, {
            cid: "VOLT_CURSFC_EXST_CD",
            cnm: "cmb_VALU_PRC2_VOLT_CURSFC_CD"
        }, {
            cid: "DRV_CLSS_DIV_TP_CD",
            cnm: "cmb_VALU_PRC2_DIV_CD"
        }
    ];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&CD_ID_M='ISU_AGNT_TP_CD','ETN_BZ_ADM_COM_TP_CD','TAX_TP_CD','DISTR_TP_CD','DRV_CLSS_LST_SETL_METHD_CD','LOSS_LMT_ETN_EARNG_STRUCT_CD','ETN_EARY_REDMPT_CYCLE_CD'";
    url += ",'VALU_PRC_CALC_INST_CD','VALU_MDL_CD','VOLT_KIND_CD','VOLT_CURSFC_EXST_CD','DRV_CLSS_DIV_TP_CD','EARY_REDMPT_CYCLE_TP_CD','EARY_REDMPT_COND_REL_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};



/**
 * LP목록 조회 시 콤보 내용 목록 조회
 */
scwin.fn_searchLPCode = function() {
    var strCbdLP = "' ':"; //초기값
    dts_LP.DataID = "/listingCommon.do?method=listLeadCom";
    dts_LP.Reset();
    for (k = 1; k <= dts_LP.getTotalRow(); k++) {
        strCbdLP = strCbdLP + (strCbdLP == "" ? "" : ",") + dts_LP.getCellData(k, "VALUE") + ":" + dts_LP.getCellData(k, "TEXT");
    }
    $c.cm.setColumnProp(grd_LP, 'LP_MBR_NO', 'Data', strCbdLP);
};


/**
 * dialog 호출용 함수
 * 상장신청 발행기관 호출관련
 */
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_SearchIsuCd); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_SearchIsuNm); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId;
    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_SearchIsuCd.setValue(arrPar[0].ISU_CD);
        txb_SearchIsuNm.setValue(arrPar[0].ISU_KOR_NM);
    }
    scwin.fn_searchLPCode(); //LP콤보내용 목록조회
    scwin.fn_getEtnBaseInfo_read_sync(); //상장원부 상세조회

};


/**
 * Etn 상장원부정보를 가져오는데 사용
 */
scwin.fn_getEtnBaseInfo_read_sync = function() {
    //상장원부정보 조회
    var url = "/etn/EtnIssueBook.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=readIssueBook&inputMessageId=ETN_ISUBOOK_SEARCH_OUT";
    url += "&SECUGRP_ID=" + scwin.fr_SecuGrpId;
    url += "&P_KEY=" + $c.stf.getObjectValue(txb_SearchIsuCd);
    dts_Etn_Isu.DataID = encodeURI(url);
    dts_Etn_Isu.Reset();

    //상장원부조기상환정보 조회
    var url = "/etn/EtnIssueBook.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=readIssueBookRedmpt&inputMessageId=ETN_ISUBOOK_SEARCH_OUT";
    url += "&SECUGRP_ID=" + scwin.fr_SecuGrpId;
    url += "&P_KEY=" + $c.stf.getObjectValue(txb_SearchIsuCd);
    dts_Etn_Redmpt_Isu.DataID = encodeURI(url);
    dts_Etn_Redmpt_Isu.Reset();


    //LP목록 조회
    url = "/etn/EtnIssueBook.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=readLpMbrNoIssueBook&inputMessageId=ETN_ISUBOOK_SEARCH_OUT";
    url += "&P_KEY=" + $c.stf.getObjectValue(txb_SearchIsuCd);
    dts_LP.DataID = encodeURI(url);
    dts_LP.Reset();

    //fn_initLpAndDistrPayGridData("N");

};
scwin.fn_initLpAndDistrPayGridData = function(initYn) {
    $c.en.fn_initLPGridData(dts_LP, initYn);
};


/**
 * 시장거래일 여부를 확인하는데 사용
 */
scwin.fn_CheckBizClose = function(obj) {
    url = "/etn/EtnIssueBook.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=checkBizClose&inputMessageId=ETN_ISUBOOK_VALID_INOUT";
    url += "&V_EXP_DD=" + $c.stf.getObjectValue(obj);
    dts_getValDt.DataID = encodeURI(url);
    dts_getValDt.Reset();
    scwin.checkResult = dts_getValDt.getCellData(1, "CALND_DD");
    scwin.mktHoldyYn = "N";
    $c.en.fn_CheckValidDate(scwin.mktHoldyYn, obj);
};


/**
  * 기준일(T)을 사용
     T-2, T+2일을 조회하는데 사용
  */
scwin.fn_CheckValidDate = function(mktHoldyYn, obj) {
    url = "/etn/EtnIssueBook.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=checkValidDate&inputMessageId=ETN_ISUBOOK_VALID_INOUT";
    url += "&V_EXP_DD=" + $c.stf.getObjectValue(obj);
    url += "&V_MKT_HOLDY_YN=" + scwin.mktHoldyYn;
    dts_getValDt.DataID = encodeURI(url);
    dts_getValDt.Reset();
    scwin.checkDateTMinus2 = dts_getValDt.getCellData(1, "CALND_DD");
    scwin.checkDateTPlus2 = dts_getValDt.getCellData(2, "CALND_DD");
};


/**
 * 일자,시간 체크 함수
 * isCheckCurDate : 오늘 날짜를 포함해서 비교를 할지 여부 ( 유가 : 미포함, 코스닥 : 포함 )
 */
scwin.checkDdTm = function(gubun, obj, msg, checkCompareDate) {
    if (obj.text.length != 8) {
        $c.win.alert("[" + msg + "일]을 정확히 입력하세요.");
        obj.focus();
        return false;
    }
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (gubun == "currDate") {
        if (scwin.vCurDate >= $c.stf.getObjectValue(obj)) {
            $c.win.alert("[" + msg + "일]을 현재일 이후로 입력하세요.");
            obj.focus();
            return false;
        }
    } else if (gubun == "ExpDdTMinus2") {
        if (checkCompareDate != $c.stf.getObjectValue(obj)) {
            $c.win.alert("[" + msg + "일]은 [만기일(T) 기준 T-2]이어야 함.");
            obj.focus();
            return false;
        }
    } else if (gubun == "ExpDdTPlus2") {
        if (checkCompareDate > $c.stf.getObjectValue(obj)) {
            $c.win.alert("[" + msg + "일]은 [만기일(T) 기준 T+2]보다 작으면 안됨.");
            obj.focus();
            return false;
        }
    } else {

    }
    return true;
};


/**
 * 상장원부 Validation 체크 함수
 */
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_EXP_DD) == "") {
        $c.win.alert("[만기일]을 입력하세요.");
        edt_EXP_DD.focus();
        return false;
    }
    if (!$c.lce.checkDdTm("currDate", edt_EXP_DD, "만기", "")) return false;
    scwin.fn_CheckBizClose(edt_EXP_DD); //만기일(T) 기준T-2, T+2 조회

    if ($c.stf.getObjectValue(txb_DISTR_PAY_BAS_DD_CONTN) == "") {
        $c.win.alert("[분배금지급기준일]을 입력하세요.");
        txb_DISTR_PAY_BAS_DD_CONTN.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_DISTR_PAY_DD_CONTN) == "") {
        $c.win.alert("[분배금지급일]을 입력하세요.");
        txb_DISTR_PAY_DD_CONTN.focus();
        return false;
    }

    /* 최종거래일은 만기일(T) 기준 T-2이어야 함(거래일 기준)*/
    if (!$c.lce.checkDdTm("ExpDdTMinus2", edt_LSTTRD_DD, "최종거래", scwin.checkDateTMinus2)) return false;
    if (!$c.lce.checkDdTm("ChkEmpty", edt_EXP_REDMPT_PRC_DECSN_STRT_DD, "만기상환가격 결정 시작")) return false;
    if (!$c.lce.checkDdTm("ChkEmpty", edt_EXP_REDMPT_PRC_DECSN_END_DD, "만기상환가격 결정 종료")) return false;
    if (!$c.stf.compareFromToDate(edt_EXP_REDMPT_PRC_DECSN_STRT_DD, edt_EXP_REDMPT_PRC_DECSN_END_DD, "만기상환가격 결정 시작일", "종료일")) return false;

    /* 만기상환금 지급일은 만기일(T) 기준 T+2 보다 작으면 안됨(거래일 기준)*/
    if (!$c.lce.checkDdTm("ExpDdTPlus2", edt_EXP_REDMPT_AMT_PAY_DD, "만기상환금 지급", scwin.checkDateTPlus2)) return false;
    if ($c.stf.getObjectValue(edt_HALFWY_REDMPT_UNIT) == "") {
        $c.win.alert("[중도상환단위]을 입력하세요.");
        edt_HALFWY_REDMPT_UNIT.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_HALFWY_REDMPT_APPL_CYCLE_CONTN) == "") {
        $c.win.alert("[중도상환 신청주기]을 입력하세요.");
        txb_HALFWY_REDMPT_APPL_CYCLE_CONTN.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_HALFWY_REDMPT_PRC_DECSN_CONTN) == "") {
        $c.win.alert("[중도상환가격 결정일]을 입력하세요.");
        txb_HALFWY_REDMPT_PRC_DECSN_CONTN.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_HALFWY_REDMPT_AMT_PAY_DD_CONTN) == "") {
        $c.win.alert("[중도상환금 지급일]을 입력하세요.");
        txb_HALFWY_REDMPT_AMT_PAY_DD_CONTN.focus();
        return false;
    }
    return true;
};



/**
 * 제3자 LP 그리드목록  dts_LP_SAVE에 설정
 */
scwin.fn_setGridDataSet = function() {
    dts_LP_SAVE.removeAll();
    var vIsuCd = dts_Etn_Isu.getCellData(1, "ISU_CD");
    for (var i = 1, j = 1; i <= dts_LP.getTotalRow(); i++) {
        var vLpMbrNo = dts_LP.getCellData(i, "LP_MBR_NO");
        if (vLpMbrNo != " " && vLpMbrNo != "") {
            dts_LP_SAVE.insertRow();
            dts_LP_SAVE.setCellData(j, "ISU_CD", vIsuCd);
            dts_LP_SAVE.setCellData(j, "LP_MBR_NO", vLpMbrNo);
            dts_LP_SAVE.setCellData(j, "LP_CONTRT_DD", ''); //not null -> null
            dts_LP_SAVE.setCellData(j, "LP_STRT_DD", ''); //not null -> null
            j++;
        }
    }
};




/**
 * update 함수
 */
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if ($c.en.fn_CheckForm()) {
        if (!$c.cp.isModified(dts_Etn_Isu) && !$c.cp.isModified(dts_LP) && !$c.cp.isModified(dts_Etn_Redmpt_Isu)) {
            $c.lce.fn_alertNoUpdate();
            return;
        }
        if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        if (scwin.vBzProcsNo.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            scwin.fn_trs(TR_JOB_UPDATE);
        }
    }
};




/**
 * Tratsaction 함수
 */
scwin.fn_trs = function(trsIdx) {
    if (scwin.TR_JOB == 'I') {
        vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB == 'U') {
        vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB == 'D') {
        vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }
    scwin.fn_setGridDataSet();
    trs_Save.Action = $c.lce.fn_encodeNSession("/etn/EtnIssueBook.do?method=updateIssueBook&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenTpCD);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.Parameters = "TRS_IDX=" + trsIdx + ",SECUGRP_ID=" + scwin.fr_SecuGrpId + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",ISU_CD=" + dts_Etn_Isu.getCellData(1, "ISU_CD") + ",ISUR_CD=" + dts_Etn_Isu.getCellData(1, "ISUR_CD") + ",LD_MKT_TP_CD=1" + ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_707;
    trs_Save.KeyValue = "JSP(I:pInput=dts_Etn_Isu, I:pInputLP=dts_LP_SAVE, I:pInputRE=dts_Etn_Redmpt_Isu)";
    trs_Save.Post();
};


/* 보증인 목록 값 Return */
scwin.fn_getSrty_code = function() {
    dts_EtnSrty.DataID = "/etn/EtnCodeAct.do?method=listSrtyCd&For=''";
    dts_EtnSrty.Reset();
};
scwin.btn_modify_onclick = function() {
    scwin.fn_update();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_Etn_Isu_OnLoadError = function() {
    $c.stf.alert_error(dts_Etn_Isu);
};
scwin.dts_Etn_Isu_OnLoadCompleted = function(rowcount) {
    var vEnable = false;
    if (dts_Etn_Isu.getCellData(1, "ETP_PROD_TP_CD") == '4') vEnable = true;
    grd_Redmpt_Isu_List.setDisabled(true);
    txa_EXP_EARNG_STRUCT_DSC_VAL.Enable = vEnable;
    cmb_VALU_PRC1_CALC_INST_CD.setDisabled(true);
    cmb_VALU_PRC1_VALU_MDL_CD.setDisabled(true);
    cmb_VALU_PRC1_VOLT_KIND_CD.setDisabled(true);
    cmb_VALU_PRC1_VOLT_CURSFC_CD.setDisabled(true);
    edt_VALU_PRC1_HIST_VOLT_PD.setDisabled(true);
    cmb_VALU_PRC1_DIV_CD.setDisabled(true);
    cmb_VALU_PRC2_CALC_INST_CD.setDisabled(true);
    cmb_VALU_PRC2_VALU_MDL_CD.setDisabled(true);
    cmb_VALU_PRC2_VOLT_KIND_CD.setDisabled(true);
    cmb_VALU_PRC2_VOLT_CURSFC_CD.setDisabled(true);
    edt_VALU_PRC2_HIST_VOLT_PD.setDisabled(true);
    cmb_VALU_PRC2_DIV_CD.setDisabled(true);
};
scwin.dts_Etn_Redmpt_Isu_OnLoadError = function() {
    $c.stf.alert_error(dts_Etn_Redmpt_Isu);
};
scwin.dts_Etn_Redmpt_Isu_OnLoadCompleted = function(rowcount) {
    if (dts_Etn_Redmpt_Isu.getCellData(1, "EARY_REDMPT_CYCLE_TP_CD") == 'O') grd_Redmpt_Isu_List.setDisabled(true);

    else grd_Redmpt_Isu_List.setDisabled(false);
};
scwin.dts_LP_OnLoadError = function() {
    $c.stf.alert_error(dts_LP);
